from pathlib import Path
import pandas as pd, geopandas as gpd
R=Path(__file__).resolve().parents[2]; O=Path(__file__).resolve().parent
p=pd.read_csv(R/'visualizations/09_population_province_map/dong_age_population.csv'); p.columns=['province','dong','population','elderly','aging']
g=gpd.read_file(R/'N3A_G0110000.shp',encoding='euc-kr').set_crs(5179,allow_override=True); codes={'11':'서울특별시','26':'부산광역시','27':'대구광역시','28':'인천광역시','29':'광주광역시','30':'대전광역시','31':'울산광역시','36':'세종특별자치시','41':'경기도','51':'강원특별자치도','43':'충청북도','44':'충청남도','52':'전북특별자치도','46':'전라남도','47':'경상북도','48':'경상남도','50':'제주특별자치도'}; g['province']=g.BJCD.astype(str).str[:2].map(codes); g['dong']=g.NAME.str.strip()
s=pd.read_csv(R/'visualizations/07_bus_stops_2025/bus_stops.csv'); q=gpd.GeoDataFrame(s,geometry=gpd.points_from_xy(s.stop_lon,s.stop_lat),crs=4326).to_crs(5179); j=gpd.sjoin(q,g[['province','dong','geometry']],predicate='within',how='left'); c=j.dropna(subset=['province']).groupby(['province','dong']).size().rename('stops').reset_index(); m=g[['province','dong','geometry']].merge(p,on=['province','dong'],how='inner').merge(c,on=['province','dong'],how='left'); m.stops=m.stops.fillna(0); m['per10k']=m.stops/m.population*10000; m.drop(columns='geometry').to_csv(O/'stop_supply_by_dong.csv',index=False,encoding='utf-8-sig'); print('unmatched',j.province.isna().sum(),'matched regions',len(m))
